{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@edo1994/opencode-queue",
  "version": "0.13.3",
  "type": "module",
  "description": "Queue OpenCode prompts and slash commands until the agent is idle",
  "main": "./dist/index.js",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "plugin",
    "queue"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mirsella/opencode-queue.git"
  },
  "bugs": {
    "url": "https://github.com/mirsella/opencode-queue/issues"
  },
  "homepage": "https://github.com/mirsella/opencode-queue#readme",
  "license": "MIT",
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    ".": "./dist/index.js"
  },
  "engines": {
    "node": ">=20.17.0"
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "test": "tsx --test index.test.js",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "effect": "4.0.0-beta.59"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.14.37",
    "@opencode-ai/sdk": "^1.14.37",
    "@types/node": "^20.0.0",
    "tsx": "^4.0.0",
    "typescript": "^6.0.3"
  },
  "overrides": {
    "uuid": "^14.0.0"
  }
}
